<script setup lang="ts">
import { computed, ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import { BASE, getToken, request } from '../../api'
import type { Product } from '../../../../shared/catalog'
import type { Review } from '../../../../shared/orders'
const reviews = ref<Review[]>([])
function checkout(offerId: number) { if(!getToken()) { uni.navigateTo({url:'/pages/login/index'});return };uni.navigateTo({url:'/pages/checkout/index?product='+productId+'&offer='+offerId}) }
const product = ref<Product | null>(null), selected = ref(0), error = ref(''), busy = ref(false), showSources = ref(false)
let productId = 0
const sku = computed(() => product.value?.skus[selected.value])
async function load() { busy.value=true; error.value=''; try { product.value=await request<Product>(`/products/${productId}`); reviews.value=await request<Review[]>(`/products/${productId}/reviews`) } catch(e) { product.value=null; error.value=e instanceof Error ? e.message : '加载失败' } finally { busy.value=false } }
onLoad(options => { productId=Number(options?.id); load() })
function copySource(url: string) { uni.setClipboardData({ data: url }) }
function preview(url: string) { uni.previewImage({ current: BASE+url, urls: sku.value?.images.map(x=>BASE+x) || [] }) }
</script>
<template><view class="screen"><view v-if="busy" class="notice">正在加载商品…</view><view v-if="error" class="notice">{{ error }}<button @click="load">重新加载</button></view><view v-if="product">
  <swiper v-if="sku?.images.length" class="gallery" indicator-dots><swiper-item v-for="url in sku.images" :key="url"><image :src="BASE+url" mode="aspectFit" @click="preview(url)" /></swiper-item></swiper>
  <view class="card"><text class="category">{{ product.category_name }} · {{ product.brand }}</text><text class="title">{{ product.name }}</text><text class="price"><text v-if="product.is_demo" class="demo-price">演示价 </text>¥ {{ product.lowest_price?.toFixed(2) }} 起</text><text class="muted">{{ product.style }} {{ product.application_space }}</text><text v-if="product.is_demo" class="demo-note">样式参考商品 · 非真实在售链接<br/>报价和库存均为课程模拟数据。</text><text class="description">{{ product.description }}</text></view>
  <view class="card"><text class="heading">选择规格</text><view class="options"><button v-for="(s,i) in product.skus" :key="s.id" :class="{active:selected===i}" @click="selected=i">{{ s.attributes.color || s.sku_code }} {{ s.attributes.size_spec }}</button></view><view v-if="sku" class="attributes"><text>尺寸：{{ sku.attributes.size_spec || '待核验' }}</text><text>规格编码：{{ sku.sku_code }}</text><text>材质：{{ sku.attributes.material || '待核验' }}</text><text>功率：{{ sku.attributes.power_watt != null ? sku.attributes.power_watt + ' W' : '待核验' }}</text><text>色温：{{ sku.attributes.color_temperature || '待核验' }}</text></view></view>
  <view class="card"><text class="heading">{{ product.is_demo ? '商家演示报价' : '商家报价' }}</text><text v-if="!sku?.offers.length" class="muted">当前规格暂无有货报价，可查看其他规格。</text><view v-for="o in sku?.offers" :key="o.id" class="offer"><view><text class="shop">{{ o.shop_name }}</text><text class="muted">库存 {{ o.stock_qty }} {{ o.unit }}</text><text class="muted">{{ o.remark }}</text></view><text class="offer-price">¥ {{ o.price.toFixed(2) }}<text>/{{ o.unit }}</text></text><button size="mini" @click="checkout(o.id)">模拟下单</button></view></view>
<view class="card"><text class="heading">已购评价</text><text v-if="!reviews.length" class="muted">暂无已购评价。</text><view v-for="r in reviews" :key="r.id" class="description"><text>{{ r.rating }} 星 · {{ r.content }}</text><text class="muted">{{ r.created_at }}</text></view></view>
<view v-if="product.demo_source" class="card sources"><text class="heading" @click="showSources = !showSources">图片与价格来源 {{ showSources ? '−' : '+' }}</text><text class="muted">摄影：{{ product.demo_source.photographer }} / {{ product.demo_source.platform }}</text><view v-if="showSources"><text class="description">{{ product.demo_source.price_note }}</text><text class="muted">核查日期：{{ product.demo_source.checked_at }}。参考价不构成同款比价或品牌背书；实时价格以来源页面为准。</text><view class="source-links"><button size="mini" @click="copySource(product.demo_source.photo_url)">复制照片来源</button><button size="mini" @click="copySource(product.demo_source.license_url)">复制素材许可</button><button size="mini" @click="copySource(product.demo_source.price_reference_url)">复制参考价来源</button></view></view></view>
</view></view></template>
<style scoped>
.screen{max-width:820px;margin:0 auto;min-height:100vh;background:#f7f5ee;padding-bottom:40rpx;color:#2d493a}.gallery{height:620rpx;background:#eeebe1}.gallery image{width:100%;height:100%}.card{background:#fff;margin:24rpx;padding:32rpx;border-radius:18rpx}.category,.muted{display:block;color:#8a927f;font-size:24rpx;line-height:1.8}.title{display:block;font-size:42rpx;line-height:1.5;margin:18rpx 0}.price{display:block;font-size:40rpx;color:#b17b48;margin:22rpx 0}.description{display:block;line-height:1.9;font-size:27rpx;margin-top:25rpx;white-space:pre-wrap}.heading{font-size:31rpx;font-weight:600}.options{display:flex;gap:14rpx;flex-wrap:wrap;margin:25rpx 0}.options button{margin:0;background:#eff1e7;color:#62735a;font-size:24rpx}.options button.active{background:#365d44;color:#fff}.attributes{display:flex;flex-direction:column;gap:13rpx;font-size:25rpx;color:#87907b}.offer{display:flex;align-items:center;justify-content:space-between;border-top:1px solid #eff1e8;padding:28rpx 0;margin-top:20rpx;gap:20rpx}.shop{font-size:29rpx}.offer-price{flex-shrink:0;display:inline-flex;align-items:baseline;color:#a36d3c;font-size:34rpx;white-space:nowrap}.offer>view{min-width:0}.offer-price text{font-size:22rpx;color:#929780}.notice{padding:80rpx 35rpx;color:#8a927f;font-size:28rpx;text-align:center}button::after{border:0}
.demo-price{font-size:25rpx}.demo-note{display:block;background:#f4f0e4;padding:18rpx;color:#857456;border-radius:10rpx;font-size:24rpx;line-height:1.8}.source-links{display:flex;gap:14rpx;flex-wrap:wrap;margin-top:24rpx}.source-links button{margin:0;font-size:22rpx;color:#48644e;background:#eff1e8}.sources .heading{display:block;cursor:pointer;margin-bottom:20rpx}.sources .description{margin-bottom:20rpx}
</style>
